import json

def transform(grid):
    """Fill 2s based on patterns."""
    result = [list(row) for row in grid]
    bg = result[0][0]
    rows = len(result)
    cols = len(result[0])

    # Step 1: Horizontal fill between for rows with multiple same non-bg values
    for r in range(rows):
        special_cells = [(c, result[r][c]) for c in range(cols) if result[r][c] != bg]

        if not special_cells:
            continue

        # Group by value
        pos_by_val = {}
        for c, val in special_cells:
            if val not in pos_by_val:
                pos_by_val[val] = []
            pos_by_val[val].append(c)

        for val, positions in pos_by_val.items():
            if len(positions) >= 2:
                # Fill between first and last occurrence
                for c in range(min(positions) + 1, max(positions)):
                    if result[r][c] == bg:
                        result[r][c] = 2

    # Step 2: For single special values, check if there's a row-mate
    # A row-mate is another row with the same value at the same column
    # If so, fill the right neighbor of that value with 2s
    for r in range(rows):
        special_cells = [(c, result[r][c]) for c in range(cols) if result[r][c] != bg]

        for c, val in special_cells:
            # Check if this is a single occurrence (only one in this row)
            row_single = True
            for other_c, other_val in special_cells:
                if other_c != c and other_val == val:
                    row_single = False
                    break

            if not row_single:
                continue

            # Check if there's a row-mate (another row with same val at same col)
            has_row_mate = False
            for rr in range(rows):
                if rr == r:
                    continue
                if result[rr][c] == val:
                    has_row_mate = True
                    break

            if has_row_mate:
                # Fill the right neighbor with 2 (if within bounds and bg)
                if c + 1 < cols and result[r][c + 1] == bg:
                    result[r][c + 1] = 2

    return result

